mapper.update:
update goods
type_id = #{typeId}, name = #{name}, img = #{img}, price = #{price}, store = #{store}, introduce = #{introduce}, sale_volume = #{saleVolume}, sale_status = #{saleStatus},
where id = #{id}

update goods
set store       = store - #{num},
    sale_volume = sale_volume + #{num}
where id = #{id}

update goods
set store       = store + #{num},
    sale_volume = sale_volume - #{num}
where id = #{id}

mapper.select:
select g.id, g.name, g.img, g.price, g.store, g.introduce, g.sale_volume, g.sale_status,gt.name as typeName,ps.nickname as shopName from goods g left join goods_type gt on g.type_id = gt.id left join pet_shop ps on g.shop_id = ps.id
and g.name like concat('%',#{name},'%') and ps.nickname like concat('%',#{shopName},'%') and g.type_id = #{typeId} and g.sale_status = #{saleStatus} and g.shop_id = #{shopId}
order by g.id desc

select count(*)
from goods
where sale_status = #{saleStatus}

select id
from goods
where shop_id = #{shopId}
